// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(this)); }

    function testFuzz_property(address observedKey, address caller) public {
        vm.deal(caller, 1 ether);

        uint beforeBal = c.balances(observedKey);

        bool ok;
        vm.prank(caller);
        try c.Deposit{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);

        uint afterBal = c.balances(observedKey);
        require(afterBal == beforeBal);
    }
}
